CREATE FUNCTION public.set_account_role(target_user uuid,new_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=target_user) THEN RAISE EXCEPTION 'الحساب غير موجود'; END IF; DELETE FROM public.user_roles WHERE user_id=target_user; INSERT INTO public.user_roles(user_id,role) VALUES(target_user,new_role); END; $$;
REVOKE ALL ON FUNCTION public.set_account_role(uuid,public.app_role) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.set_account_role(uuid,public.app_role) TO service_role;
